#!/usr/bin/env python3
"""Inventory what a candidate GHC's compiler needs from outside itself.

`../notes/phase0/feature-scan.py` sizes the *syntax* gap. This sizes the gap that
actually decides whether MicroHs can compile an old GHC:

  * which modules the compiler imports that it does not define itself, split
    by whether MicroHs already provides them;
  * how deeply it reaches into GHC's own RTS and primops;
  * which of its "source" files are really generated by another Haskell tool,
    since each such tool is its own bootstrap problem.

Heuristic and line-based, like feature-scan: triage, not a front end.

    ./import-inventory.py <compiler-tree> [...] [--mhs-lib=PATH]
"""
import re, sys, os, collections, importlib.util

# feature-scan.py has a hyphen in its name, so it cannot be imported by name;
# load it by path to reuse its literate-Haskell lexer rather than copy it.
_HERE = os.path.dirname(os.path.abspath(__file__))
_spec = importlib.util.spec_from_file_location(
    "feature_scan", os.path.join(_HERE, os.pardir, "phase0", "feature-scan.py"))
_fs = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_fs)
code_lines = _fs.code_lines

# Pre-hierarchical Haskell 98 library names. Old GHC spells them this way;
# MicroHs ships the same modules under their hierarchical names, so these are
# an alias shim, not missing functionality.
ALIASES = {
    "List": "Data.List", "Char": "Data.Char", "Maybe": "Data.Maybe",
    "Monad": "Control.Monad", "Array": "Data.Array", "Ratio": "Data.Ratio",
    "Bits": "Data.Bits", "Word": "Data.Word", "Int": "Data.Int",
    "Complex": "Data.Complex", "IO": "System.IO", "System": "System.Environment",
    "Directory": "System.Directory", "CPUTime": "System.CPUTime",
    "Exception": "Control.Exception", "ST": "Control.Monad.ST",
    "IOExts": "Data.IORef", "Numeric": "Numeric", "Random": "System.Random",
    "Time": "Data.Time", "Ix": "Data.Ix", "FiniteMap": "Data.Map",
    "Set": "Data.Set", "Concurrent": "Control.Concurrent",
}

# MicroHs ships parts of base under its own names. Mhs.Array is a complete
# Data.Array (array/listArray/accumArray/(!)/(//)/accum/ixmap, re-exporting
# Data.Ix); Mhs.MutArr / Mhs.MutUArr / Mhs.UArr are the mutable and unboxed
# machinery that the Data.Array.* class interface would sit on.
MHS_ALIASES = {
    "Data.Array": "Mhs.Array", "Data.Array.IArray": "Mhs.Array",
    "Data.Array.MArray": "Mhs.MutArr", "Data.Array.ST": "Mhs.MutArr",
    "Data.Array.Unboxed": "Mhs.UArr", "Data.Array.Base": "Mhs.Arr",
}


def resolve(m):
    """Follow a module name through both alias maps, e.g. Array -> Data.Array
    -> Mhs.Array."""
    seen = set()
    while m in ALIASES or m in MHS_ALIASES:
        if m in seen:
            break
        seen.add(m)
        m = ALIASES.get(m) or MHS_ALIASES.get(m)
    return m


# Tools that generate Haskell from a non-Haskell source. Each is itself a
# Haskell program, so each is its own bootstrap problem -- and each generated
# file shipped in a tarball is generated code, not source.
GENERATORS = {".y": "happy", ".ly": "happy", ".x": "alex", ".lx": "alex",
              ".hsc": "hsc2hs"}
BANNER = re.compile(r"produced by.{0,20}Happy|generated by Alex|"
                    r"Machine generated.{0,40}hsc2hs|DO NOT EDIT", re.I)

IMPORT = re.compile(
    r"^\s*import\s+(?P<source>\{-#\s*SOURCE\s*#-\}\s*)?"
    r"(?:qualified\s+)?(?P<mod>[A-Z][\w.']*)")
MODULE = re.compile(r"^\s*module\s+([A-Z][\w.']*)")
PRAGMA = re.compile(r"\{-#.*?#-\}")

# Unboxed names split three ways, because they are not equally diagnostic.
# Capitalised (Int#, I#) and symbolic (+#, ==#) names are unambiguously GHC's;
# lowercase ones mix real primops with GHC's habit of naming ordinary unboxed
# locals `len#`, `barr#`, which no line-based scan can tell apart.
PRIM_CON = re.compile(r"\b([A-Z][A-Za-z0-9_']*#+)")
PRIM_SYM = re.compile(r"(?<![\w'])([-+*/<>=~^!&|.]+#+)")
PRIM_VAR = re.compile(r"\b([a-z_][A-Za-z0-9_']*#+)")
UNBOXED_LIT = re.compile(r"(?<![\w'])(\d+)#")

# Modules that are GHC's own guts rather than a portable library. Reaching
# into these is the part of the port a shim cannot simply forward.
RTS_PREFIXES = ("GHC.", "Prel")
RTS_MODULES = {"GlaExts", "Addr", "ByteArray", "MutableArray", "ArrBase",
               "PackBase", "STBase", "IOBase", "ConcBase", "CCall"}


def is_rts(m):
    # "Prelude" starts with "Prel" and is not an internal module
    return m != "Prelude" and (m in RTS_MODULES or m.startswith(RTS_PREFIXES))


def generator_of(fname):
    """The tool that generates fname, if it is a generator source.

    GHC 6.10 renames its grammars to Parser.y.pp.source / Lexer.x.source so
    the build uses the shipped generated .hs instead, so strip those too.
    """
    stem = fname
    for suffix in (".source", ".pp"):
        if stem.endswith(suffix):
            stem = stem[: -len(suffix)]
    base, ext = os.path.splitext(stem)
    return (base, GENERATORS[ext]) if ext in GENERATORS else (None, None)


def mhs_modules(lib_root):
    """Module names MicroHs's lib/ provides, taken from its file layout."""
    mods = set()
    for dp, _, files in os.walk(lib_root):
        for f in files:
            if f.endswith(".hs"):
                rel = os.path.relpath(os.path.join(dp, f), lib_root)
                mods.add(rel[:-3].replace(os.sep, "."))
    return mods


def classify_files(roots):
    """Split the tree into real source, generated Haskell, and grammars."""
    source, generated, grammars = [], {}, {}
    for root in roots:
        for dp, _, files in os.walk(root):
            for f in sorted(files):
                mod, tool = generator_of(f)
                if tool:
                    grammars[mod] = tool
                    continue
                if not f.endswith((".hs", ".lhs")):
                    continue
                p = os.path.join(dp, f)
                with open(p, encoding="utf-8", errors="replace") as fh:
                    head = "".join(next(fh, "") for _ in range(25))
                if BANNER.search(head):
                    generated[os.path.splitext(f)[0]] = p
                else:
                    source.append(p)
    # a shipped .hs beside its own grammar is generated even without a banner
    for mod in list(grammars):
        for p in list(source):
            if os.path.splitext(os.path.basename(p))[0] == mod:
                generated.setdefault(mod, p)
                source.remove(p)
    return source, generated, grammars


def inventory(paths):
    defined, imports, source_imports = set(), collections.Counter(), collections.Counter()
    prim = {k: collections.Counter() for k in ("con", "sym", "var")}
    unboxed_lits = nlines = 0
    for p in paths:
        for line in code_lines(p):
            nlines += 1
            if line.lstrip().startswith("--"):
                continue
            m = MODULE.match(line)
            if m:
                defined.add(m.group(1))
            m = IMPORT.match(line)
            if m:
                imports[m.group("mod")] += 1
                if m.group("source"):
                    source_imports[m.group("mod")] += 1
            line = PRAGMA.sub(" ", line)          # {-# ... #-} is not a primop
            for kind, rx in (("con", PRIM_CON), ("sym", PRIM_SYM), ("var", PRIM_VAR)):
                for op in rx.findall(line):
                    prim[kind][op] += 1
            unboxed_lits += len(UNBOXED_LIT.findall(line))
    return dict(defined=defined, imports=imports, source_imports=source_imports,
                prim=prim, unboxed_lits=unboxed_lits, nlines=nlines)


def report(inv, nfiles, generated, grammars, mhs, gen_inv=None):
    defined, imports = inv["defined"], inv["imports"]
    known = defined | set(generated) | set(grammars)
    rts, have, alias, gap = {}, {}, {}, {}
    for m, n in imports.items():
        if m in known:
            continue
        (rts if is_rts(m) else
         have if m in mhs else
         alias if resolve(m) in mhs else gap)[m] = n

    print(f"{nfiles} source modules, {inv['nlines']} code lines")
    print(f"{len(defined)} modules defined in tree, "
          f"{len(rts) + len(have) + len(alias) + len(gap)} distinct external imports\n")

    print(f"{'bucket':28} {'modules':>8} {'sites':>7}")
    print("-" * 46)
    for name, d in (("GHC RTS / primop internals", rts),
                    ("provided by MicroHs lib", have),
                    ("provided, needs alias", alias),
                    ("gap (shim or package)", gap)):
        print(f"{name:28} {len(d):>8} {sum(d.values()):>7}")
    print()

    print("GHC internals imported (import sites):")
    for m, n in sorted(rts.items(), key=lambda kv: -kv[1]):
        print(f"  {n:4}  {m}")
    print()

    print("pre-hierarchical names MicroHs has under another spelling:")
    for m, n in sorted(alias.items(), key=lambda kv: -kv[1]):
        print(f"  {n:4}  {m:18} -> {resolve(m)}")
    print()

    print("gap modules, most-imported first:")
    for m, n in sorted(gap.items(), key=lambda kv: -kv[1])[:25]:
        print(f"  {n:4}  {m}")
    print()

    if grammars or generated:
        print("not hand-written source:")
        for mod, tool in sorted(grammars.items()):
            shipped = "generated .hs shipped" if mod in generated else "must run " + tool
            print(f"  {mod:16} {tool:8} {shipped}")
        for mod in sorted(set(generated) - set(grammars)):
            print(f"  {mod:16} {'?':8} generated banner, no grammar in tree")
        if gen_inv and gen_inv["nlines"]:
            gp = sum(sum(c.values()) for c in gen_inv["prim"].values())
            print(f"  -> excluded from the counts above: {len(generated)} files, "
                  f"{gen_inv['nlines']} code lines, {gp} unboxed uses.")
            print("     mhs still has to compile these; they are just not source.")
        print()

    src = inv["source_imports"]
    print(f"mutual recursion: {sum(src.values())} {{-# SOURCE #-}} imports "
          f"naming {len(src)} modules\n")

    prim = inv["prim"]
    tot = sum(sum(c.values()) for c in prim.values())
    print(f"unboxed: {tot} uses, plus {inv['unboxed_lits']} unboxed literals")
    print(f"  unboxed types/constructors : {sum(prim['con'].values()):5} uses, "
          f"{len(prim['con']):4} distinct")
    print(f"  symbolic primops (+#, ==#) : {sum(prim['sym'].values()):5} uses, "
          f"{len(prim['sym']):4} distinct")
    print(f"  lowercase #-names          : {sum(prim['var'].values()):5} uses, "
          f"{len(prim['var']):4} distinct  (primops AND unboxed locals)")
    print()
    for kind, label in (("con", "unboxed types/constructors"), ("sym", "symbolic primops")):
        print(f"top {label}:")
        print("   ", "  ".join(f"{op}({n})" for op, n in prim[kind].most_common(12)))


if __name__ == "__main__":
    roots = [a for a in sys.argv[1:] if not a.startswith("--")] or ["."]
    lib = next((a.split("=", 1)[1] for a in sys.argv[1:] if a.startswith("--mhs-lib=")),
               os.path.join(_HERE, os.pardir, "MicroHs", "lib"))
    mhs = mhs_modules(lib) if os.path.isdir(lib) else set()
    if not mhs:
        print(f"warning: no MicroHs lib at {lib}; 'provided' bucket will be empty",
              file=sys.stderr)
    src, gen, gram = classify_files(roots)
    report(inventory(src), len(src), gen, gram, mhs, inventory(list(gen.values())))
